{
  "contract": "WAsgard",
  "closure": {
    "site_function": "claimInactiveAccountDividends",
    "site_call": ".call",
    "functions": [
      "claimDividends",
      "unwrap",
      "wrap"
    ],
    "justification": "These functions interact with the exposed storage variables 'lastClaimTimes' and 'withdrawnDividends'."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "claimDividends",
      "unwrap",
      "wrap"
    ],
    "nesting_bound": {
      "claimDividends": 1,
      "unwrap": 1,
      "wrap": 1
    }
  },
  "phases": {
    "function": "claimInactiveAccountDividends",
    "pre": {
      "name": "pre",
      "from_marker": "entry",
      "to_marker": "before_call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_call",
      "to_marker": "after_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_call",
      "to_marker": "exit"
    },
    "linearization_point": "before_call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Tracks the amount of dividends in-flight during the callback window.",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_sum__balances == _totalSupply + inFlight",
    "stable_formula": "_sum__balances == _totalSupply",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "_sum__balances == _totalSupply",
    "rule": "The exposure invariant ensures conservation of balances across the callback window."
  }
}
